    copy_column(v, stride, rows, base + 206, base + 206);
    copy_column(v, stride, rows, base + 207, base + 207);
    copy_column(v, stride, rows, base + 208, base + 208);
    copy_column(v, stride, rows, base + 209, base + 209);
    copy_column(v, stride, rows, base + 210, base + 210);
    for lane in 0..rows { v[(base + 206) * stride + lane] = add(&v[(base + 20) * stride + lane], &v[(base + 206) * stride + lane]); }
